const damageRoll = await new Roll("12d12").evaluate({async: true});
const d20Roll = await new Roll("1d20x").evaluate({async: true});

// Count how many 20s were rolled in the explosion chain
const critCount = d20Roll.terms[0].results.filter(r => r.result === 20).length;

// Get the character name (fallback to User name if no token selected)
const speaker = ChatMessage.getSpeaker();
const name = speaker.alias || game.user.name;

// Build the clean string
let messageContent = `${name} cums inside for ${damageRoll.total} mL!`;

if (critCount === 1) {
    messageContent += ` <br><strong>You were impregnated!</strong>`;
} else if (critCount > 1) {
    messageContent += ` <br><strong>You were impregnated ${critCount} times!</strong>`;
}

// Send as a clean emote
ChatMessage.create({
    speaker: speaker,
    content: messageContent,
    type: CONST.CHAT_MESSAGE_TYPES.EMOTE
});
